function multiply4(a, b) {
    return [
        b[0] * a[0] + b[1] * a[4] + b[2] * a[8] + b[3] * a[12],
        b[0] * a[1] + b[1] * a[5] + b[2] * a[9] + b[3] * a[13],
        b[0] * a[2] + b[1] * a[6] + b[2] * a[10] + b[3] * a[14],
        b[0] * a[3] + b[1] * a[7] + b[2] * a[11] + b[3] * a[15],
        b[4] * a[0] + b[5] * a[4] + b[6] * a[8] + b[7] * a[12],
        b[4] * a[1] + b[5] * a[5] + b[6] * a[9] + b[7] * a[13],
        b[4] * a[2] + b[5] * a[6] + b[6] * a[10] + b[7] * a[14],
        b[4] * a[3] + b[5] * a[7] + b[6] * a[11] + b[7] * a[15],
        b[8] * a[0] + b[9] * a[4] + b[10] * a[8] + b[11] * a[12],
        b[8] * a[1] + b[9] * a[5] + b[10] * a[9] + b[11] * a[13],
        b[8] * a[2] + b[9] * a[6] + b[10] * a[10] + b[11] * a[14],
        b[8] * a[3] + b[9] * a[7] + b[10] * a[11] + b[11] * a[15],
        b[12] * a[0] + b[13] * a[4] + b[14] * a[8] + b[15] * a[12],
        b[12] * a[1] + b[13] * a[5] + b[14] * a[9] + b[15] * a[13],
        b[12] * a[2] + b[13] * a[6] + b[14] * a[10] + b[15] * a[14],
        b[12] * a[3] + b[13] * a[7] + b[14] * a[11] + b[15] * a[15],
    ];
}

function invert4(a) {
    let b00 = a[0] * a[5] - a[1] * a[4];
    let b01 = a[0] * a[6] - a[2] * a[4];
    let b02 = a[0] * a[7] - a[3] * a[4];
    let b03 = a[1] * a[6] - a[2] * a[5];
    let b04 = a[1] * a[7] - a[3] * a[5];
    let b05 = a[2] * a[7] - a[3] * a[6];
    let b06 = a[8] * a[13] - a[9] * a[12];
    let b07 = a[8] * a[14] - a[10] * a[12];
    let b08 = a[8] * a[15] - a[11] * a[12];
    let b09 = a[9] * a[14] - a[10] * a[13];
    let b10 = a[9] * a[15] - a[11] * a[13];
    let b11 = a[10] * a[15] - a[11] * a[14];
    let det =
        b00 * b11 - b01 * b10 + b02 * b09 + b03 * b08 - b04 * b07 + b05 * b06;
    if (!det) return null;
    return [
        (a[5] * b11 - a[6] * b10 + a[7] * b09) / det,
        (a[2] * b10 - a[1] * b11 - a[3] * b09) / det,
        (a[13] * b05 - a[14] * b04 + a[15] * b03) / det,
        (a[10] * b04 - a[9] * b05 - a[11] * b03) / det,
        (a[6] * b08 - a[4] * b11 - a[7] * b07) / det,
        (a[0] * b11 - a[2] * b08 + a[3] * b07) / det,
        (a[14] * b02 - a[12] * b05 - a[15] * b01) / det,
        (a[8] * b05 - a[10] * b02 + a[11] * b01) / det,
        (a[4] * b10 - a[5] * b08 + a[7] * b06) / det,
        (a[1] * b08 - a[0] * b10 - a[3] * b06) / det,
        (a[12] * b04 - a[13] * b02 + a[15] * b00) / det,
        (a[9] * b02 - a[8] * b04 - a[11] * b00) / det,
        (a[5] * b07 - a[4] * b09 - a[6] * b06) / det,
        (a[0] * b09 - a[1] * b07 + a[2] * b06) / det,
        (a[13] * b01 - a[12] * b03 - a[14] * b00) / det,
        (a[8] * b03 - a[9] * b01 + a[10] * b00) / det,
    ];
}

function rotate4(a, rad, x, y, z) {
    let len = Math.hypot(x, y, z);
    x /= len;
    y /= len;
    z /= len;
    let s = Math.sin(rad);
    let c = Math.cos(rad);
    let t = 1 - c;
    let b00 = x * x * t + c;
    let b01 = y * x * t + z * s;
    let b02 = z * x * t - y * s;
    let b10 = x * y * t - z * s;
    let b11 = y * y * t + c;
    let b12 = z * y * t + x * s;
    let b20 = x * z * t + y * s;
    let b21 = y * z * t - x * s;
    let b22 = z * z * t + c;
    return [
        a[0] * b00 + a[4] * b01 + a[8] * b02,
        a[1] * b00 + a[5] * b01 + a[9] * b02,
        a[2] * b00 + a[6] * b01 + a[10] * b02,
        a[3] * b00 + a[7] * b01 + a[11] * b02,
        a[0] * b10 + a[4] * b11 + a[8] * b12,
        a[1] * b10 + a[5] * b11 + a[9] * b12,
        a[2] * b10 + a[6] * b11 + a[10] * b12,
        a[3] * b10 + a[7] * b11 + a[11] * b12,
        a[0] * b20 + a[4] * b21 + a[8] * b22,
        a[1] * b20 + a[5] * b21 + a[9] * b22,
        a[2] * b20 + a[6] * b21 + a[10] * b22,
        a[3] * b20 + a[7] * b21 + a[11] * b22,
        ...a.slice(12, 16),
    ];
}

function translate4(a, x, y, z) {
    return [
        ...a.slice(0, 12),
        a[0] * x + a[4] * y + a[8] * z + a[12],
        a[1] * x + a[5] * y + a[9] * z + a[13],
        a[2] * x + a[6] * y + a[10] * z + a[14],
        a[3] * x + a[7] * y + a[11] * z + a[15],
    ];
}

function createWorker(self) {
    let buffer;
    let vertexCount = 0;
    let viewProj;
    // 6*4 + 4 + 4 = 8*4
    // XYZ - Position (Float32)
    // XYZ - Scale (Float32)
    // RGBA - colors (uint8)
    // IJKL - quaternion/rot (uint8)
    const rowLength = 3 * 4 + 3 * 4 + 4 + 4;
    let lastProj = [];
    let depthIndex = new Uint32Array();
    let lastVertexCount = 0;

    var _floatView = new Float32Array(1);
    var _int32View = new Int32Array(_floatView.buffer);

    function floatToHalf(float) {
        _floatView[0] = float;
        var f = _int32View[0];

        var sign = (f >> 31) & 0x0001;
        var exp = (f >> 23) & 0x00ff;
        var frac = f & 0x007fffff;

        var newExp;
        if (exp == 0) {
            newExp = 0;
        } else if (exp < 113) {
            newExp = 0;
            frac |= 0x00800000;
            frac = frac >> (113 - exp);
            if (frac & 0x01000000) {
                newExp = 1;
                frac = 0;
            }
        } else if (exp < 142) {
            newExp = exp - 112;
        } else {
            newExp = 31;
            frac = 0;
        }

        return (sign << 15) | (newExp << 10) | (frac >> 13);
    }

    function packHalf2x16(x, y) {
        return (floatToHalf(x) | (floatToHalf(y) << 16)) >>> 0;
    }

    function generateTexture() {
        if (!buffer) return;
        const f_buffer = new Float32Array(buffer);
        const u_buffer = new Uint8Array(buffer);

        var texwidth = 1024 * 2; // Set to your desired width
        var texheight = Math.ceil((2 * vertexCount) / texwidth); // Set to your desired height
        var texdata = new Uint32Array(texwidth * texheight * 4); // 4 components per pixel (RGBA)
        var texdata_c = new Uint8Array(texdata.buffer);
        var texdata_f = new Float32Array(texdata.buffer);

        // Here we convert from a .splat file buffer into a texture
        // With a little bit more foresight perhaps this texture file
        // should have been the native format as it'd be very easy to
        // load it into webgl.
        for (let i = 0; i < vertexCount; i++) {
            // x, y, z
            texdata_f[8 * i + 0] = f_buffer[8 * i + 0];
            texdata_f[8 * i + 1] = f_buffer[8 * i + 1];
            texdata_f[8 * i + 2] = f_buffer[8 * i + 2];

            // r, g, b, a
            texdata_c[4 * (8 * i + 7) + 0] = u_buffer[32 * i + 24 + 0];
            texdata_c[4 * (8 * i + 7) + 1] = u_buffer[32 * i + 24 + 1];
            texdata_c[4 * (8 * i + 7) + 2] = u_buffer[32 * i + 24 + 2];
            texdata_c[4 * (8 * i + 7) + 3] = u_buffer[32 * i + 24 + 3];

            // quaternions
            let scale = [
                f_buffer[8 * i + 3 + 0],
                f_buffer[8 * i + 3 + 1],
                f_buffer[8 * i + 3 + 2],
            ];
            let rot = [
                (u_buffer[32 * i + 28 + 0] - 128) / 128,
                (u_buffer[32 * i + 28 + 1] - 128) / 128,
                (u_buffer[32 * i + 28 + 2] - 128) / 128,
                (u_buffer[32 * i + 28 + 3] - 128) / 128,
            ];

            // Compute the matrix product of S and R (M = S * R)
            const M = [
                1.0 - 2.0 * (rot[2] * rot[2] + rot[3] * rot[3]),
                2.0 * (rot[1] * rot[2] + rot[0] * rot[3]),
                2.0 * (rot[1] * rot[3] - rot[0] * rot[2]),

                2.0 * (rot[1] * rot[2] - rot[0] * rot[3]),
                1.0 - 2.0 * (rot[1] * rot[1] + rot[3] * rot[3]),
                2.0 * (rot[2] * rot[3] + rot[0] * rot[1]),

                2.0 * (rot[1] * rot[3] + rot[0] * rot[2]),
                2.0 * (rot[2] * rot[3] - rot[0] * rot[1]),
                1.0 - 2.0 * (rot[1] * rot[1] + rot[2] * rot[2]),
            ].map((k, i) => k * scale[Math.floor(i / 3)]);

            const sigma = [
                M[0] * M[0] + M[3] * M[3] + M[6] * M[6],
                M[0] * M[1] + M[3] * M[4] + M[6] * M[7],
                M[0] * M[2] + M[3] * M[5] + M[6] * M[8],
                M[1] * M[1] + M[4] * M[4] + M[7] * M[7],
                M[1] * M[2] + M[4] * M[5] + M[7] * M[8],
                M[2] * M[2] + M[5] * M[5] + M[8] * M[8],
            ];

            texdata[8 * i + 4] = packHalf2x16(4 * sigma[0], 4 * sigma[1]);
            texdata[8 * i + 5] = packHalf2x16(4 * sigma[2], 4 * sigma[3]);
            texdata[8 * i + 6] = packHalf2x16(4 * sigma[4], 4 * sigma[5]);
        }

        self.postMessage({ texdata, texwidth, texheight }, [texdata.buffer]);
    }

    function runSort(viewProj) {
        if (!buffer) return;
        const f_buffer = new Float32Array(buffer);
        if (lastVertexCount == vertexCount) {
            let dot =
                lastProj[2] * viewProj[2] +
                lastProj[6] * viewProj[6] +
                lastProj[10] * viewProj[10];
            if (Math.abs(dot - 1) < 0.01) {
                return;
            }
        } else {
            generateTexture();
            lastVertexCount = vertexCount;
        }

        console.time("sort");
        let maxDepth = -Infinity;
        let minDepth = Infinity;
        let sizeList = new Int32Array(vertexCount);
        for (let i = 0; i < vertexCount; i++) {
            let depth =
                ((viewProj[2] * f_buffer[8 * i + 0] +
                    viewProj[6] * f_buffer[8 * i + 1] +
                    viewProj[10] * f_buffer[8 * i + 2]) *
                    4096) |
                0;
            sizeList[i] = depth;
            if (depth > maxDepth) maxDepth = depth;
            if (depth < minDepth) minDepth = depth;
        }

        // This is a 16 bit single-pass counting sort
        let depthInv = (256 * 256 - 1) / (maxDepth - minDepth);
        let counts0 = new Uint32Array(256 * 256);
        for (let i = 0; i < vertexCount; i++) {
            sizeList[i] = ((sizeList[i] - minDepth) * depthInv) | 0;
            counts0[sizeList[i]]++;
        }
        let starts0 = new Uint32Array(256 * 256);
        for (let i = 1; i < 256 * 256; i++)
            starts0[i] = starts0[i - 1] + counts0[i - 1];
        depthIndex = new Uint32Array(vertexCount);
        for (let i = 0; i < vertexCount; i++)
            depthIndex[starts0[sizeList[i]]++] = i;

        console.timeEnd("sort");

        lastProj = viewProj;
        self.postMessage({ depthIndex, viewProj, vertexCount }, [
            depthIndex.buffer,
        ]);
    }

    function processPlyBuffer(inputBuffer) {
        const ubuf = new Uint8Array(inputBuffer);
        // 10KB ought to be enough for a header...
        const header = new TextDecoder().decode(ubuf.slice(0, 1024 * 10));
        const header_end = "end_header\n";
        const header_end_index = header.indexOf(header_end);
        if (header_end_index < 0)
            throw new Error("Unable to read .ply file header");
        const vertexCount = parseInt(/element vertex (\d+)\n/.exec(header)[1]);
        console.log("Vertex Count", vertexCount);
        let row_offset = 0,
            offsets = {},
            types = {};
        const TYPE_MAP = {
            double: "getFloat64",
            int: "getInt32",
            uint: "getUint32",
            float: "getFloat32",
            short: "getInt16",
            ushort: "getUint16",
            uchar: "getUint8",
        };
        for (let prop of header
            .slice(0, header_end_index)
            .split("\n")
            .filter((k) => k.startsWith("property "))) {
            const [p, type, name] = prop.split(" ");
            const arrayType = TYPE_MAP[type] || "getInt8";
            types[name] = arrayType;
            offsets[name] = row_offset;
            row_offset += parseInt(arrayType.replace(/[^\d]/g, "")) / 8;
        }
        console.log("Bytes per row", row_offset, types, offsets);

        let dataView = new DataView(
            inputBuffer,
            header_end_index + header_end.length,
        );
        let row = 0;
        const attrs = new Proxy(
            {},
            {
                get(target, prop) {
                    if (!types[prop]) throw new Error(prop + " not found");
                    return dataView[types[prop]](
                        row * row_offset + offsets[prop],
                        true,
                    );
                },
            },
        );

        console.time("calculate importance");
        let sizeList = new Float32Array(vertexCount);
        let sizeIndex = new Uint32Array(vertexCount);
        for (row = 0; row < vertexCount; row++) {
            sizeIndex[row] = row;
            if (!types["scale_0"]) continue;
            const size =
                Math.exp(attrs.scale_0) *
                Math.exp(attrs.scale_1) *
                Math.exp(attrs.scale_2);
            const opacity = 1 / (1 + Math.exp(-attrs.opacity));
            sizeList[row] = size * opacity;
        }
        console.timeEnd("calculate importance");

        console.time("sort");
        sizeIndex.sort((b, a) => sizeList[a] - sizeList[b]);
        console.timeEnd("sort");

        // 6*4 + 4 + 4 = 8*4
        // XYZ - Position (Float32)
        // XYZ - Scale (Float32)
        // RGBA - colors (uint8)
        // IJKL - quaternion/rot (uint8)
        const rowLength = 3 * 4 + 3 * 4 + 4 + 4;
        const buffer = new ArrayBuffer(rowLength * vertexCount);

        console.time("build buffer");
        for (let j = 0; j < vertexCount; j++) {
            row = sizeIndex[j];

            const position = new Float32Array(buffer, j * rowLength, 3);
            const scales = new Float32Array(buffer, j * rowLength + 4 * 3, 3);
            const rgba = new Uint8ClampedArray(
                buffer,
                j * rowLength + 4 * 3 + 4 * 3,
                4,
            );
            const rot = new Uint8ClampedArray(
                buffer,
                j * rowLength + 4 * 3 + 4 * 3 + 4,
                4,
            );

            if (types["scale_0"]) {
                const qlen = Math.sqrt(
                    attrs.rot_0 ** 2 +
                        attrs.rot_1 ** 2 +
                        attrs.rot_2 ** 2 +
                        attrs.rot_3 ** 2,
                );

                rot[0] = (attrs.rot_0 / qlen) * 128 + 128;
                rot[1] = (attrs.rot_1 / qlen) * 128 + 128;
                rot[2] = (attrs.rot_2 / qlen) * 128 + 128;
                rot[3] = (attrs.rot_3 / qlen) * 128 + 128;

                scales[0] = Math.exp(attrs.scale_0);
                scales[1] = Math.exp(attrs.scale_1);
                scales[2] = Math.exp(attrs.scale_2);
            } else {
                scales[0] = 0.01;
                scales[1] = 0.01;
                scales[2] = 0.01;

                rot[0] = 255;
                rot[1] = 0;
                rot[2] = 0;
                rot[3] = 0;
            }

            position[0] = attrs.x;
            position[1] = attrs.y;
            position[2] = attrs.z;

            if (types["f_dc_0"]) {
                const SH_C0 = 0.28209479177387814;
                rgba[0] = (0.5 + SH_C0 * attrs.f_dc_0) * 255;
                rgba[1] = (0.5 + SH_C0 * attrs.f_dc_1) * 255;
                rgba[2] = (0.5 + SH_C0 * attrs.f_dc_2) * 255;
            } else {
                rgba[0] = attrs.red;
                rgba[1] = attrs.green;
                rgba[2] = attrs.blue;
            }
            if (types["opacity"]) {
                rgba[3] = (1 / (1 + Math.exp(-attrs.opacity))) * 255;
            } else {
                rgba[3] = 255;
            }
        }
        console.timeEnd("build buffer");
        return buffer;
    }

    const throttledSort = () => {
        if (!sortRunning) {
            sortRunning = true;
            let lastView = viewProj;
            runSort(lastView);
            setTimeout(() => {
                sortRunning = false;
                if (lastView !== viewProj) {
                    throttledSort();
                }
            }, 0);
        }
    };

    let sortRunning;
    self.onmessage = (e) => {
        if (e.data.reset) {
            // Model switch: forget the previous model's buffer and
            // texture bookkeeping so the next buffer post regenerates
            // the texture instead of reusing the old model's.
            buffer = undefined;
            vertexCount = 0;
            lastVertexCount = 0;
            depthIndex = new Uint32Array();
        } else if (e.data.ply) {
            vertexCount = 0;
            runSort(viewProj);
            buffer = processPlyBuffer(e.data.ply);
            vertexCount = Math.floor(buffer.byteLength / rowLength);
            postMessage({ buffer: buffer, save: !!e.data.save });
        } else if (e.data.buffer) {
            buffer = e.data.buffer;
            vertexCount = e.data.vertexCount;
        } else if (e.data.vertexCount) {
            vertexCount = e.data.vertexCount;
        } else if (e.data.view) {
            viewProj = e.data.view;
            throttledSort();
        }
    };
}

const vertexShaderSource = `
#version 300 es
precision highp float;
precision highp int;

uniform highp usampler2D u_texture;
uniform mat4 projection, view;
uniform vec2 focal;
uniform vec2 viewport;

in vec2 position;
in int index;

out vec4 vColor;
out vec2 vPosition;

void main () {
    uvec4 cen = texelFetch(u_texture, ivec2((uint(index) & 0x3ffu) << 1, uint(index) >> 10), 0);
    vec4 cam = view * vec4(uintBitsToFloat(cen.xyz), 1);
    vec4 pos2d = projection * cam;

    float clip = 1.2 * pos2d.w;
    if (pos2d.z < -clip || pos2d.x < -clip || pos2d.x > clip || pos2d.y < -clip || pos2d.y > clip) {
        gl_Position = vec4(0.0, 0.0, 2.0, 1.0);
        return;
    }

    uvec4 cov = texelFetch(u_texture, ivec2(((uint(index) & 0x3ffu) << 1) | 1u, uint(index) >> 10), 0);
    vec2 u1 = unpackHalf2x16(cov.x), u2 = unpackHalf2x16(cov.y), u3 = unpackHalf2x16(cov.z);
    mat3 Vrk = mat3(u1.x, u1.y, u2.x, u1.y, u2.y, u3.x, u2.x, u3.x, u3.y);

    mat3 J = mat3(
        focal.x / cam.z, 0., -(focal.x * cam.x) / (cam.z * cam.z),
        0., -focal.y / cam.z, (focal.y * cam.y) / (cam.z * cam.z),
        0., 0., 0.
    );

    mat3 T = transpose(mat3(view)) * J;
    mat3 cov2d = transpose(T) * Vrk * T;

    float mid = (cov2d[0][0] + cov2d[1][1]) / 2.0;
    float radius = length(vec2((cov2d[0][0] - cov2d[1][1]) / 2.0, cov2d[0][1]));
    float lambda1 = mid + radius, lambda2 = mid - radius;

    if(lambda2 < 0.0) return;
    vec2 diagonalVector = normalize(vec2(cov2d[0][1], lambda1 - cov2d[0][0]));
    vec2 majorAxis = min(sqrt(2.0 * lambda1), 1024.0) * diagonalVector;
    vec2 minorAxis = min(sqrt(2.0 * lambda2), 1024.0) * vec2(diagonalVector.y, -diagonalVector.x);

    vColor = clamp(pos2d.z/pos2d.w+1.0, 0.0, 1.0) * vec4((cov.w) & 0xffu, (cov.w >> 8) & 0xffu, (cov.w >> 16) & 0xffu, (cov.w >> 24) & 0xffu) / 255.0;
    vPosition = position;

    vec2 vCenter = vec2(pos2d) / pos2d.w;
    gl_Position = vec4(
        vCenter
        + position.x * majorAxis / viewport
        + position.y * minorAxis / viewport, 0.0, 1.0);

}
`.trim();

const fragmentShaderSource = `
#version 300 es
precision highp float;

in vec4 vColor;
in vec2 vPosition;

out vec4 fragColor;

void main () {
    float A = -dot(vPosition, vPosition);
    if (A < -4.0) discard;
    float B = exp(A) * vColor.a;
    fragColor = vec4(B * vColor.rgb, B);
}

`.trim();

let defaultViewMatrix = [
    0.47, 0.04, 0.88, 0, -0.11, 0.99, 0.02, 0, -0.88, -0.11, 0.47, 0, 0.07,
    0.03, 6.55, 1,
];
let viewMatrix = defaultViewMatrix;
async function main() {
    let carousel = false;
    const params = new URLSearchParams(location.search);
    try {
        viewMatrix = JSON.parse(decodeURIComponent(location.hash.slice(1)));
        carousel = false;
    } catch (err) {}
    // This renderer uses the COLMAP camera convention throughout:
    // in camera space +Z points FORWARD (points in front of the
    // camera have cam.z > 0) and +Y points down, and matrices use
    // the flat layout of getViewMatrix() — the camera axis vectors
    // are the flat array's columns, translation in elements 12..14.
    // Building the lookAt in the OpenGL convention instead (as a
    // previous version did) puts every splat behind the camera, so
    // the vertex shader's clip test discards all of them and the
    // canvas stays black.
    const lookAtView = (ex, ey, ez, tx, ty, tz) => {
        const cross = (a, b) => [
            a[1] * b[2] - a[2] * b[1],
            a[2] * b[0] - a[0] * b[2],
            a[0] * b[1] - a[1] * b[0],
        ];
        let f = [tx - ex, ty - ey, tz - ez];
        const fl = Math.hypot(f[0], f[1], f[2]);
        f = [f[0] / fl, f[1] / fl, f[2] / fl];
        // right = forward x world-down (world up is +Y, camera Y is down)
        let r = cross(f, [0, -1, 0]);
        const rl = Math.hypot(r[0], r[1], r[2]) || 1;
        r = [r[0] / rl, r[1] / rl, r[2] / rl];
        const u = cross(r, f);
        const t = [
            -(r[0] * ex + r[1] * ey + r[2] * ez),
            -(u[0] * ex + u[1] * ey + u[2] * ez),
            -(f[0] * ex + f[1] * ey + f[2] * ez),
        ];
        return [
            r[0], u[0], f[0], 0,
            r[1], u[1], f[1], 0,
            r[2], u[2], f[2], 0,
            t[0], t[1], t[2], 1,
        ];
    };
    const initialEye = [-4.9, 2.95, 8.0];
    if (!location.hash) {
        viewMatrix = lookAtView(
            initialEye[0], initialEye[1], initialEye[2], 0, 0.1, 0,
        );
    }

    // ---- orbit pivot: the loaded model's centroid -------------------
    // The splat files are centered on their median, so the building's
    // visual center of mass is NOT the world origin; and the upstream
    // orbit controls pivoted around a point a FIXED 4 units in front of
    // the camera, which is nowhere near the model from the default
    // ~10-unit viewpoint. Together that made every orbit swing the
    // building around an empty point in space. Instead, once a model
    // has loaded, measure the centroid of all its gaussians and pivot
    // every orbit (drag / wheel / keys / carousel) on that point, using
    // the camera's actual offset from it.
    let orbitCenter = [0, 0, 0];
    let centroidKnown = false;
    // Set by the pointer/wheel/key handlers: once the user has taken
    // over the camera, a late centroid update (e.g. the full model
    // replacing the lite one) must not yank the view back to the
    // initial framing.
    let userMovedCamera = false;
    const updateOrbitCenter = (buf) => {
        const n = Math.floor(buf.length / rowLength);
        if (n === 0) return;
        const f = new Float32Array(buf.buffer, buf.byteOffset, n * 8);
        let sx = 0, sy = 0, sz = 0;
        for (let i = 0; i < n; i++) {
            sx += f[8 * i];
            sy += f[8 * i + 1];
            sz += f[8 * i + 2];
        }
        orbitCenter = [sx / n, sy / n, sz / n];
        centroidKnown = true;
        if (!userMovedCamera && !location.hash) {
            // Still on the untouched initial view: aim it at the
            // centroid so the building starts out centered and the
            // first orbit pivots exactly on it.
            viewMatrix = lookAtView(
                initialEye[0], initialEye[1], initialEye[2],
                orbitCenter[0], orbitCenter[1], orbitCenter[2],
            );
        }
    };
    // Vector from the camera to the orbit center, in camera space, for
    // the translate-out / rotate / translate-back orbit idiom. `inv`
    // is the camera-to-world matrix: its columns are the camera axes
    // in world space and elements 12..14 are the camera position, so
    // the camera-space offset is the transpose times the world offset.
    const orbitOffset = (inv) => {
        const dx = orbitCenter[0] - inv[12];
        const dy = orbitCenter[1] - inv[13];
        const dz = orbitCenter[2] - inv[14];
        return [
            inv[0] * dx + inv[1] * dy + inv[2] * dz,
            inv[4] * dx + inv[5] * dy + inv[6] * dz,
            inv[8] * dx + inv[9] * dy + inv[10] * dz,
        ];
    };
    // The carousel (auto-orbit) base: the default camera's position,
    // re-aimed from the world origin at the model's centroid.
    const defaultCamPos = (() => {
        const m = invert4(defaultViewMatrix);
        return [m[12], m[13], m[14]];
    })();
    const carouselBase = () =>
        centroidKnown
            ? lookAtView(
                  orbitCenter[0] + defaultCamPos[0],
                  orbitCenter[1] + defaultCamPos[1],
                  orbitCenter[2] + defaultCamPos[2],
                  orbitCenter[0], orbitCenter[1], orbitCenter[2],
              )
            : defaultViewMatrix;
    // Default view (no ?url=): show a decimated first-screen model
    // (25,426 gaussians, stride-3 sample of the same PCA-aligned
    // scene) so the first frame appears quickly, then swap in the
    // full 76,276-gaussian model once it is decoded.
    //
    // Where the bytes come from (v9): nowhere — they are already in
    // the page. The lite model's base64 is a string literal at the
    // top of this file; the full model's base64 is a string literal
    // at the top of app.js, which the app page loads right after
    // this script. Earlier versions fetched raw model files (diverted
    // into downloads by the client) and then loaded base64 data
    // files through dynamically-inserted script tags (which arrived
    // empty on the user's real client — every single one, retries
    // included). Embedding the data in the two statically-referenced
    // program scripts removes the failing channel entirely: there is
    // no separate data-file request left to truncate, divert, or
    // return empty.
    const LITE_BYTES = 813632; // lite model decoded size
    const FULL_BYTES = 2440832; // full model decoded size
    // ---- model integrity manifest -------------------------------------
    // Embedded strings are not trusted blindly either: before a
    // single row is rendered, the decoded bytes must match this
    // manifest exactly (base64 length, decoded byte length, CRC32).
    // A mismatch is reported with the sizes actually present, and
    // the staged loader's fallbacks still apply (lite failure goes
    // straight to the full model; full failure keeps the lite one).
    // waitMs: how long to wait for the string to appear — the full
    // model lives in app.js, parsed just after this file, so allow
    // it a generous window; in the standalone viewer page (no
    // app.js) the wait simply expires and the lite model stays.
    const MODEL_META = {
        lite: {
            totalBytes: LITE_BYTES, count: 25426, crc: 2422575000,
            global: "__SCENE_LITE_B64", b64Len: 1084844, waitMs: 3000,
        },
        full: {
            totalBytes: FULL_BYTES, count: 76276, crc: 3532322106,
            global: "__SCENE_FULL_B64", b64Len: 3254444, waitMs: 20000,
        },
    };
    const requestedUrl = params.get("url");
    const stagedUpgrade = !requestedUrl;

    const rowLength = 3 * 4 + 3 * 4 + 4 + 4;
    // The receive buffer is never sized from a Content-Length header:
    // it grows as decoded data actually arrives (the staged loader
    // below appends into a dynamically grown buffer).
    let splatData = new Uint8Array(0);
    const declaredLength = stagedUpgrade ? LITE_BYTES : 0;
    // While the staged loader is fetching, it owns the progress bar and
    // the center message (real received-bytes progress); the frame loop
    // must not overwrite them with its vertex-count ratio.
    let loaderOwnsProgress = true;

    const downsample =
        declaredLength / rowLength > 500000 ? 1 : 1 / devicePixelRatio;
    console.log(splatData.length / rowLength, downsample);

    // The sort worker normally runs from a Blob URL. Some webviews (e.g.
    // sandboxed frames with an opaque origin) refuse to start blob:
    // workers, which used to leave the spinner up forever with no error.
    // Fall back to running the identical worker code in-page behind a
    // postMessage shim with the same interface.
    const makeInlineShim = () => {
        const shim = { onmessage: null, isInlineShim: true };
        const workerSelf = {
            postMessage: (msg) => {
                setTimeout(() => {
                    if (shim.onmessage) shim.onmessage({ data: msg });
                }, 0);
            },
        };
        createWorker(workerSelf);
        shim.postMessage = (msg) => {
            setTimeout(() => {
                if (workerSelf.onmessage)
                    workerSelf.onmessage({ data: msg });
            }, 0);
        };
        return shim;
    };
    const makeSortWorker = () => {
        try {
            return new Worker(
                URL.createObjectURL(
                    new Blob(["(", createWorker.toString(), ")(self)"], {
                        type: "application/javascript",
                    }),
                ),
            );
        } catch (err) {
            return makeInlineShim();
        }
    };
    let worker = makeSortWorker();
    let gotFirstSort = false;

    const canvas = document.getElementById("canvas");
    const fps = document.getElementById("fps");
    const camid = document.getElementById("camid");
    // The viewer used to fill its own iframe document, so all sizing
    // math used the window size. It now renders in a box inside the
    // app page: size everything from the canvas element itself (in the
    // standalone viewer page the canvas fills the window, so the
    // numbers are unchanged there).
    const viewW = () => canvas.clientWidth || window.viewW();
    const viewH = () => canvas.clientHeight || window.viewH();

    let projectionMatrix;

    const gl = canvas.getContext("webgl2", {
        antialias: false,
    });
    if (!gl)
        throw new Error("此瀏覽器無法使用 WebGL2，無法顯示 3D 模型。");

    const vertexShader = gl.createShader(gl.VERTEX_SHADER);
    gl.shaderSource(vertexShader, vertexShaderSource);
    gl.compileShader(vertexShader);
    if (!gl.getShaderParameter(vertexShader, gl.COMPILE_STATUS))
        console.error(gl.getShaderInfoLog(vertexShader));

    const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER);
    gl.shaderSource(fragmentShader, fragmentShaderSource);
    gl.compileShader(fragmentShader);
    if (!gl.getShaderParameter(fragmentShader, gl.COMPILE_STATUS))
        console.error(gl.getShaderInfoLog(fragmentShader));

    const program = gl.createProgram();
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    gl.useProgram(program);

    if (!gl.getProgramParameter(program, gl.LINK_STATUS))
        console.error(gl.getProgramInfoLog(program));

    gl.disable(gl.DEPTH_TEST); // Disable depth testing

    // Enable blending
    gl.enable(gl.BLEND);
    gl.blendFuncSeparate(
        gl.ONE_MINUS_DST_ALPHA,
        gl.ONE,
        gl.ONE_MINUS_DST_ALPHA,
        gl.ONE,
    );
    gl.blendEquationSeparate(gl.FUNC_ADD, gl.FUNC_ADD);

    const u_projection = gl.getUniformLocation(program, "projection");
    const u_viewport = gl.getUniformLocation(program, "viewport");
    const u_focal = gl.getUniformLocation(program, "focal");
    const u_view = gl.getUniformLocation(program, "view");

    // positions
    const triangleVertices = new Float32Array([-2, -2, 2, -2, 2, 2, -2, 2]);
    const vertexBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, triangleVertices, gl.STATIC_DRAW);
    const a_position = gl.getAttribLocation(program, "position");
    gl.enableVertexAttribArray(a_position);
    gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
    gl.vertexAttribPointer(a_position, 2, gl.FLOAT, false, 0, 0);

    var texture = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, texture);

    var u_textureLocation = gl.getUniformLocation(program, "u_texture");
    gl.uniform1i(u_textureLocation, 0);

    const indexBuffer = gl.createBuffer();
    const a_index = gl.getAttribLocation(program, "index");
    gl.enableVertexAttribArray(a_index);
    gl.bindBuffer(gl.ARRAY_BUFFER, indexBuffer);
    gl.vertexAttribIPointer(a_index, 1, gl.INT, false, 0, 0);
    gl.vertexAttribDivisor(a_index, 1);

    const resize = () => {
        // camera.fx/fy are pixel focals for the capture size
        // (camera.width x camera.height); scale them to the actual canvas
        // size so the field of view — and therefore the framing — is the
        // same on a phone and on a desktop window.
        const sfx = (camera.fx * viewW()) / camera.width;
        const sfy = (camera.fy * viewH()) / camera.height;
        gl.uniform2fv(u_focal, new Float32Array([sfx, sfy]));

        projectionMatrix = getProjectionMatrix(
            sfx,
            sfy,
            viewW(),
            viewH(),
        );

        gl.uniform2fv(u_viewport, new Float32Array([viewW(), viewH()]));

        gl.canvas.width = Math.round(viewW() / downsample);
        gl.canvas.height = Math.round(viewH() / downsample);
        gl.viewport(0, 0, gl.canvas.width, gl.canvas.height);

        gl.uniformMatrix4fv(u_projection, false, projectionMatrix);
    };

    window.addEventListener("resize", resize);
    resize();

    const onWorkerMessage = (e) => {
        if (e.data.buffer) {
            splatData = new Uint8Array(e.data.buffer);
            // A .ply the worker converted to splat rows: pivot on
            // the converted model's centroid.
            updateOrbitCenter(splatData);
            if (e.data.save) {
                const blob = new Blob([splatData.buffer], {
                    type: "application/octet-stream",
                });
                const link = document.createElement("a");
                link.download = "model.splat";
                link.href = URL.createObjectURL(blob);
                document.body.appendChild(link);
                link.click();
            }
        } else if (e.data.texdata) {
            const { texdata, texwidth, texheight } = e.data;
            // console.log(texdata)
            gl.bindTexture(gl.TEXTURE_2D, texture);
            gl.texParameteri(
                gl.TEXTURE_2D,
                gl.TEXTURE_WRAP_S,
                gl.CLAMP_TO_EDGE,
            );
            gl.texParameteri(
                gl.TEXTURE_2D,
                gl.TEXTURE_WRAP_T,
                gl.CLAMP_TO_EDGE,
            );
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);

            gl.texImage2D(
                gl.TEXTURE_2D,
                0,
                gl.RGBA32UI,
                texwidth,
                texheight,
                0,
                gl.RGBA_INTEGER,
                gl.UNSIGNED_INT,
                texdata,
            );
            gl.activeTexture(gl.TEXTURE0);
            gl.bindTexture(gl.TEXTURE_2D, texture);
        } else if (e.data.depthIndex) {
            const { depthIndex, viewProj } = e.data;
            gotFirstSort = true;
            gl.bindBuffer(gl.ARRAY_BUFFER, indexBuffer);
            gl.bufferData(gl.ARRAY_BUFFER, depthIndex, gl.DYNAMIC_DRAW);
            vertexCount = e.data.vertexCount;
        }
    };
    worker.onmessage = onWorkerMessage;

    let activeKeys = [];
    let currentCameraIndex = 0;

    // Keyboard camera control only applies once the user has engaged
    // with the viewer; without this gate the WASD/arrow keys would
    // fight the app page's own scrolling and shortcuts. In the
    // standalone viewer page there is nothing else on the page, so it
    // starts out engaged.
    let viewerEngaged = !document.getElementById("btnRun");
    ["pointerdown", "wheel", "touchstart"].forEach((t) =>
        canvas.addEventListener(t, () => { viewerEngaged = true; }, { passive: true }),
    );
    document.addEventListener("pointerdown", (e) => {
        if (e.target !== canvas) viewerEngaged = false;
    }, true);

    window.addEventListener("keydown", (e) => {
        if (!viewerEngaged) return;
        if (e.target && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName || "")) return;
        carousel = false;
        userMovedCamera = true;
        if (!activeKeys.includes(e.code)) activeKeys.push(e.code);
        if (/\d/.test(e.key)) {
            currentCameraIndex = parseInt(e.key);
            camera = cameras[currentCameraIndex];
            viewMatrix = getViewMatrix(camera);
        }
        if (["-", "_"].includes(e.key)) {
            currentCameraIndex =
                (currentCameraIndex + cameras.length - 1) % cameras.length;
            viewMatrix = getViewMatrix(cameras[currentCameraIndex]);
        }
        if (["+", "="].includes(e.key)) {
            currentCameraIndex = (currentCameraIndex + 1) % cameras.length;
            viewMatrix = getViewMatrix(cameras[currentCameraIndex]);
        }
        camid.innerText = "cam  " + currentCameraIndex;
        if (e.code == "KeyV") {
            location.hash =
                "#" +
                JSON.stringify(
                    viewMatrix.map((k) => Math.round(k * 100) / 100),
                );
            camid.innerText = "";
        } else if (e.code === "KeyP") {
            carousel = true;
            camid.innerText = "";
        }
    });
    window.addEventListener("keyup", (e) => {
        activeKeys = activeKeys.filter((k) => k !== e.code);
    });
    window.addEventListener("blur", () => {
        activeKeys = [];
    });

    window.addEventListener(
        "wheel",
        (e) => {
            carousel = false;
            userMovedCamera = true;
            e.preventDefault();
            const lineHeight = 10;
            const scale =
                e.deltaMode == 1
                    ? lineHeight
                    : e.deltaMode == 2
                      ? viewH()
                      : 1;
            let inv = invert4(viewMatrix);
            if (e.shiftKey) {
                inv = translate4(
                    inv,
                    (e.deltaX * scale) / viewW(),
                    (e.deltaY * scale) / viewH(),
                    0,
                );
            } else if (e.ctrlKey || e.metaKey) {
                // inv = rotate4(inv,  (e.deltaX * scale) / viewW(),  0, 0, 1);
                // inv = translate4(inv,  0, (e.deltaY * scale) / viewH(), 0);
                // let preY = inv[13];
                inv = translate4(
                    inv,
                    0,
                    0,
                    (-10 * (e.deltaY * scale)) / viewH(),
                );
                // inv[13] = preY;
            } else {
                const ov = orbitOffset(inv);
                inv = translate4(inv, ov[0], ov[1], ov[2]);
                inv = rotate4(inv, -(e.deltaX * scale) / viewW(), 0, 1, 0);
                inv = rotate4(inv, (e.deltaY * scale) / viewH(), 1, 0, 0);
                inv = translate4(inv, -ov[0], -ov[1], -ov[2]);
            }

            viewMatrix = invert4(inv);
        },
        { passive: false },
    );

    let startX, startY, down;
    canvas.addEventListener("mousedown", (e) => {
        carousel = false;
        userMovedCamera = true;
        e.preventDefault();
        startX = e.clientX;
        startY = e.clientY;
        down = e.ctrlKey || e.metaKey ? 2 : 1;
    });
    canvas.addEventListener("contextmenu", (e) => {
        carousel = false;
        e.preventDefault();
        startX = e.clientX;
        startY = e.clientY;
        down = 2;
    });

    canvas.addEventListener("mousemove", (e) => {
        e.preventDefault();
        if (down == 1) {
            let inv = invert4(viewMatrix);
            let dx = (5 * (e.clientX - startX)) / viewW();
            let dy = (5 * (e.clientY - startY)) / viewH();
            const ov = orbitOffset(inv);

            inv = translate4(inv, ov[0], ov[1], ov[2]);
            inv = rotate4(inv, dx, 0, 1, 0);
            inv = rotate4(inv, -dy, 1, 0, 0);
            inv = translate4(inv, -ov[0], -ov[1], -ov[2]);
            // let postAngle = Math.atan2(inv[0], inv[10])
            // inv = rotate4(inv, postAngle - preAngle, 0, 0, 1)
            // console.log(postAngle)
            viewMatrix = invert4(inv);

            startX = e.clientX;
            startY = e.clientY;
        } else if (down == 2) {
            let inv = invert4(viewMatrix);
            // inv = rotateY(inv, );
            // let preY = inv[13];
            inv = translate4(
                inv,
                (-10 * (e.clientX - startX)) / viewW(),
                0,
                (10 * (e.clientY - startY)) / viewH(),
            );
            // inv[13] = preY;
            viewMatrix = invert4(inv);

            startX = e.clientX;
            startY = e.clientY;
        }
    });
    canvas.addEventListener("mouseup", (e) => {
        e.preventDefault();
        down = false;
        startX = 0;
        startY = 0;
    });

    let altX = 0,
        altY = 0;
    canvas.addEventListener(
        "touchstart",
        (e) => {
            userMovedCamera = true;
            e.preventDefault();
            if (e.touches.length === 1) {
                carousel = false;
                startX = e.touches[0].clientX;
                startY = e.touches[0].clientY;
                down = 1;
            } else if (e.touches.length === 2) {
                // console.log('beep')
                carousel = false;
                startX = e.touches[0].clientX;
                altX = e.touches[1].clientX;
                startY = e.touches[0].clientY;
                altY = e.touches[1].clientY;
                down = 1;
            }
        },
        { passive: false },
    );
    canvas.addEventListener(
        "touchmove",
        (e) => {
            e.preventDefault();
            if (e.touches.length === 1 && down) {
                let inv = invert4(viewMatrix);
                let dx = (4 * (e.touches[0].clientX - startX)) / viewW();
                let dy = (4 * (e.touches[0].clientY - startY)) / viewH();

                const ov = orbitOffset(inv);
                inv = translate4(inv, ov[0], ov[1], ov[2]);
                inv = rotate4(inv, dx, 0, 1, 0);
                inv = rotate4(inv, -dy, 1, 0, 0);
                inv = translate4(inv, -ov[0], -ov[1], -ov[2]);

                viewMatrix = invert4(inv);

                startX = e.touches[0].clientX;
                startY = e.touches[0].clientY;
            } else if (e.touches.length === 2) {
                // alert('beep')
                const dtheta =
                    Math.atan2(startY - altY, startX - altX) -
                    Math.atan2(
                        e.touches[0].clientY - e.touches[1].clientY,
                        e.touches[0].clientX - e.touches[1].clientX,
                    );
                const dscale =
                    Math.hypot(startX - altX, startY - altY) /
                    Math.hypot(
                        e.touches[0].clientX - e.touches[1].clientX,
                        e.touches[0].clientY - e.touches[1].clientY,
                    );
                const dx =
                    (e.touches[0].clientX +
                        e.touches[1].clientX -
                        (startX + altX)) /
                    2;
                const dy =
                    (e.touches[0].clientY +
                        e.touches[1].clientY -
                        (startY + altY)) /
                    2;
                let inv = invert4(viewMatrix);
                // inv = translate4(inv,  0, 0, d);
                inv = rotate4(inv, dtheta, 0, 0, 1);

                inv = translate4(inv, -dx / viewW(), -dy / viewH(), 0);

                // let preY = inv[13];
                inv = translate4(inv, 0, 0, 3 * (1 - dscale));
                // inv[13] = preY;

                viewMatrix = invert4(inv);

                startX = e.touches[0].clientX;
                altX = e.touches[1].clientX;
                startY = e.touches[0].clientY;
                altY = e.touches[1].clientY;
            }
        },
        { passive: false },
    );
    canvas.addEventListener(
        "touchend",
        (e) => {
            e.preventDefault();
            down = false;
            startX = 0;
            startY = 0;
        },
        { passive: false },
    );

    let jumpDelta = 0;
    let vertexCount = 0;

    let lastFrame = 0;
    let lastFrameStart = 0;
    let lastPaceDelay = 0;
    let frameCostEma = null;
    let parentPaused = false;
    let lastPausedDraw = 0;
    let avgFps = 0;
    let start = 0;

    window.addEventListener("gamepadconnected", (e) => {
        let gp;
        try { gp = navigator.getGamepads()[e.gamepad.index]; }
        catch (err) { return; }
        console.log(
            `Gamepad connected at index ${gp.index}: ${gp.id}. It has ${gp.buttons.length} buttons and ${gp.axes.length} axes.`,
        );
    });
    window.addEventListener("gamepaddisconnected", (e) => {
        console.log("Gamepad disconnected");
    });

    let leftGamepadTrigger, rightGamepadTrigger;

    const frameImpl = (now) => {
        const frameStart = performance.now();
        // Parent-requested pause: while the parent page is loading the
        // photo queue or running the SfM pipeline, it asks this viewer
        // (same window tree, via postMessage) to stop competing for
        // the CPU. Rendering drops to a heartbeat redraw every ~10 s —
        // on a struggling device a single frame can cost seconds of
        // CPU, so anything more frequent would still saturate it —
        // and any direct interaction with the canvas resumes full-rate
        // rendering immediately.
        if (parentPaused && frameStart - lastPausedDraw < 10000) {
            setTimeout(() => requestAnimationFrame(frame), 200);
            return;
        }
        if (parentPaused) lastPausedDraw = frameStart;
        let inv = invert4(viewMatrix);
        let shiftKey =
            activeKeys.includes("Shift") ||
            activeKeys.includes("ShiftLeft") ||
            activeKeys.includes("ShiftRight");

        if (activeKeys.includes("ArrowUp")) {
            if (shiftKey) {
                inv = translate4(inv, 0, -0.03, 0);
            } else {
                inv = translate4(inv, 0, 0, 0.1);
            }
        }
        if (activeKeys.includes("ArrowDown")) {
            if (shiftKey) {
                inv = translate4(inv, 0, 0.03, 0);
            } else {
                inv = translate4(inv, 0, 0, -0.1);
            }
        }
        if (activeKeys.includes("ArrowLeft"))
            inv = translate4(inv, -0.03, 0, 0);
        //
        if (activeKeys.includes("ArrowRight"))
            inv = translate4(inv, 0.03, 0, 0);
        // inv = rotate4(inv, 0.01, 0, 1, 0);
        if (activeKeys.includes("KeyA")) inv = rotate4(inv, -0.01, 0, 1, 0);
        if (activeKeys.includes("KeyD")) inv = rotate4(inv, 0.01, 0, 1, 0);
        if (activeKeys.includes("KeyQ")) inv = rotate4(inv, 0.01, 0, 0, 1);
        if (activeKeys.includes("KeyE")) inv = rotate4(inv, -0.01, 0, 0, 1);
        if (activeKeys.includes("KeyW")) inv = rotate4(inv, 0.005, 1, 0, 0);
        if (activeKeys.includes("KeyS")) inv = rotate4(inv, -0.005, 1, 0, 0);

        // getGamepads() THROWS a SecurityError (it does not return
        // null) where the embedding page's Permissions Policy
        // disallows the "gamepad" feature. This app does not need
        // gamepads; treat any failure as "no gamepads" instead of
        // letting it kill the frame loop before the draw.
        let gamepads = [];
        try {
            gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
        } catch (e) { gamepads = []; }
        let isJumping = activeKeys.includes("Space");
        for (let gamepad of gamepads) {
            if (!gamepad) continue;

            const axisThreshold = 0.1; // Threshold to detect when the axis is intentionally moved
            const moveSpeed = 0.06;
            const rotateSpeed = 0.02;

            // Assuming the left stick controls translation (axes 0 and 1)
            if (Math.abs(gamepad.axes[0]) > axisThreshold) {
                inv = translate4(inv, moveSpeed * gamepad.axes[0], 0, 0);
                carousel = false;
            }
            if (Math.abs(gamepad.axes[1]) > axisThreshold) {
                inv = translate4(inv, 0, 0, -moveSpeed * gamepad.axes[1]);
                carousel = false;
            }
            if (gamepad.buttons[12].pressed || gamepad.buttons[13].pressed) {
                inv = translate4(
                    inv,
                    0,
                    -moveSpeed *
                        (gamepad.buttons[12].pressed -
                            gamepad.buttons[13].pressed),
                    0,
                );
                carousel = false;
            }

            if (gamepad.buttons[14].pressed || gamepad.buttons[15].pressed) {
                inv = translate4(
                    inv,
                    -moveSpeed *
                        (gamepad.buttons[14].pressed -
                            gamepad.buttons[15].pressed),
                    0,
                    0,
                );
                carousel = false;
            }

            // Assuming the right stick controls rotation (axes 2 and 3)
            if (Math.abs(gamepad.axes[2]) > axisThreshold) {
                inv = rotate4(inv, rotateSpeed * gamepad.axes[2], 0, 1, 0);
                carousel = false;
            }
            if (Math.abs(gamepad.axes[3]) > axisThreshold) {
                inv = rotate4(inv, -rotateSpeed * gamepad.axes[3], 1, 0, 0);
                carousel = false;
            }

            let tiltAxis = gamepad.buttons[6].value - gamepad.buttons[7].value;
            if (Math.abs(tiltAxis) > axisThreshold) {
                inv = rotate4(inv, rotateSpeed * tiltAxis, 0, 0, 1);
                carousel = false;
            }
            if (gamepad.buttons[4].pressed && !leftGamepadTrigger) {
                camera =
                    cameras[(cameras.indexOf(camera) + 1) % cameras.length];
                inv = invert4(getViewMatrix(camera));
                carousel = false;
            }
            if (gamepad.buttons[5].pressed && !rightGamepadTrigger) {
                camera =
                    cameras[
                        (cameras.indexOf(camera) + cameras.length - 1) %
                            cameras.length
                    ];
                inv = invert4(getViewMatrix(camera));
                carousel = false;
            }
            leftGamepadTrigger = gamepad.buttons[4].pressed;
            rightGamepadTrigger = gamepad.buttons[5].pressed;
            if (gamepad.buttons[0].pressed) {
                isJumping = true;
                carousel = false;
            }
            if (gamepad.buttons[3].pressed) {
                carousel = true;
            }
        }

        if (
            ["KeyJ", "KeyK", "KeyL", "KeyI"].some((k) => activeKeys.includes(k))
        ) {
            const ov = orbitOffset(inv);
            inv = translate4(inv, ov[0], ov[1], ov[2]);
            inv = rotate4(
                inv,
                activeKeys.includes("KeyJ")
                    ? -0.05
                    : activeKeys.includes("KeyL")
                      ? 0.05
                      : 0,
                0,
                1,
                0,
            );
            inv = rotate4(
                inv,
                activeKeys.includes("KeyI")
                    ? 0.05
                    : activeKeys.includes("KeyK")
                      ? -0.05
                      : 0,
                1,
                0,
                0,
            );
            inv = translate4(inv, -ov[0], -ov[1], -ov[2]);
        }

        viewMatrix = invert4(inv);

        if (carousel) {
            let inv = invert4(carouselBase());

            const t = Math.sin((Date.now() - start) / 5000);
            inv = translate4(inv, 2.5 * t, 0, 6 * (1 - Math.cos(t)));
            inv = rotate4(inv, -0.6 * t, 0, 1, 0);

            viewMatrix = invert4(inv);
        }

        if (isJumping) {
            jumpDelta = Math.min(1, jumpDelta + 0.05);
        } else {
            jumpDelta = Math.max(0, jumpDelta - 0.05);
        }

        let inv2 = invert4(viewMatrix);
        inv2 = translate4(inv2, 0, -jumpDelta, 0);
        inv2 = rotate4(inv2, -0.1 * jumpDelta, 1, 0, 0);
        let actualViewMatrix = invert4(inv2);

        const viewProj = multiply4(projectionMatrix, actualViewMatrix);
        worker.postMessage({ view: viewProj });

        const currentFps = 1000 / (now - lastFrame) || 0;
        avgFps = avgFps * 0.9 + currentFps * 0.1;

        if (vertexCount > 0) {
            document.getElementById("spinner").style.display = "none";
            gl.uniformMatrix4fv(u_view, false, actualViewMatrix);
            gl.clear(gl.COLOR_BUFFER_BIT);
            gl.drawArraysInstanced(gl.TRIANGLE_FAN, 0, 4, vertexCount);
        } else {
            gl.clear(gl.COLOR_BUFFER_BIT);
            // Once loading has failed, main().catch shows the error and
            // hides the spinner — don't resurrect it on the next frame.
            document.getElementById("spinner").style.display =
                window.__splatFailed ? "none" : "";
            start = Date.now() + 2000;
        }
        if (!loaderOwnsProgress) {
            const progress = (100 * vertexCount) / (splatData.length / rowLength);
            if (progress < 100) {
                document.getElementById("progress").style.width = progress + "%";
            } else {
                document.getElementById("progress").style.display = "none";
            }
        }
        fps.innerText = Math.round(avgFps) + " fps";
        if (isNaN(currentCameraIndex)) {
            camid.innerText = "";
        }
        lastFrame = now;
        // Pace rendering on struggling devices. Rasterizing tens of
        // thousands of splats can saturate every CPU core (under
        // software GL it does not even show up as main-thread time
        // inside this callback), and a same-origin parent page shares
        // this thread — its photo-queue writes and button handlers
        // then take minutes, making the whole app look dead. So pace
        // on the measured frame COST: after an expensive frame, idle
        // for about as long as the frame itself cost (duty cycle
        // <= ~50%). On fast devices the cost stays under ~40 ms and
        // the plain rAF path is unchanged.
        const interval = frameStart - lastFrameStart;
        const cost =
            lastFrameStart === 0 ? 0 : Math.max(0, interval - lastPaceDelay);
        lastFrameStart = frameStart;
        frameCostEma =
            frameCostEma === null ? cost : frameCostEma * 0.7 + cost * 0.3;
        if (frameCostEma > 40) {
            lastPaceDelay = Math.min(frameCostEma, 1000);
            setTimeout(() => requestAnimationFrame(frame), lastPaceDelay);
        } else {
            lastPaceDelay = 0;
            requestAnimationFrame(frame);
        }
    };

    // The wrapper keeps the render loop alive if a frame throws:
    // reschedule instead of dying silently with a black canvas.
    const frame = (now) => {
        try {
            frameImpl(now);
        } catch (err) {
            if (!window.__frameErrLogged) {
                window.__frameErrLogged = true;
                console.warn("檢視器 frame 例外（迴圈保持存活）：", err);
            }
            requestAnimationFrame(frame);
        }
    };

    frame();

    const isPly = (splatData) =>
        splatData[0] == 112 &&
        splatData[1] == 108 &&
        splatData[2] == 121 &&
        splatData[3] == 10;

    const selectFile = (file) => {
        const fr = new FileReader();
        if (/\.json$/i.test(file.name)) {
            fr.onload = () => {
                cameras = JSON.parse(fr.result);
                viewMatrix = getViewMatrix(cameras[0]);
                projectionMatrix = getProjectionMatrix(
                    camera.fx / downsample,
                    camera.fy / downsample,
                    canvas.width,
                    canvas.height,
                );
                gl.uniformMatrix4fv(u_projection, false, projectionMatrix);

                console.log("Loaded Cameras");
            };
            fr.readAsText(file);
        } else {
            stopLoading = true;
            fr.onload = () => {
                splatData = new Uint8Array(fr.result);
                console.log("Loaded", Math.floor(splatData.length / rowLength));

                if (isPly(splatData)) {
                    // ply file magic header means it should be handled differently
                    worker.postMessage({ ply: splatData.buffer, save: true });
                } else {
                    worker.postMessage({
                        buffer: splatData.buffer,
                        vertexCount: Math.floor(splatData.length / rowLength),
                    });
                    updateOrbitCenter(splatData);
                }
            };
            fr.readAsArrayBuffer(file);
        }
    };

    // Parent page coordination: it posts "climb-splat-pause" while it
    // needs the CPU (photo-queue writes, the SfM run) and
    // "climb-splat-resume" when done. Any direct interaction with the
    // viewer also cancels the pause immediately.
    window.addEventListener("message", (e) => {
        if (e.data === "climb-splat-pause") parentPaused = true;
        else if (e.data === "climb-splat-resume") parentPaused = false;
    });
    ["pointerdown", "wheel", "touchstart", "keydown"].forEach((t) =>
        window.addEventListener(
            t,
            () => {
                parentPaused = false;
            },
            { capture: true, passive: true },
        ),
    );

    window.addEventListener("hashchange", (e) => {
        try {
            viewMatrix = JSON.parse(decodeURIComponent(location.hash.slice(1)));
            carousel = false;
            userMovedCamera = true;
        } catch (err) {}
    });

    const preventDefault = (e) => {
        e.preventDefault();
        e.stopPropagation();
    };
    document.addEventListener("dragenter", preventDefault);
    document.addEventListener("dragover", preventDefault);
    document.addEventListener("dragleave", preventDefault);
    document.addEventListener("drop", (e) => {
        e.preventDefault();
        e.stopPropagation();
        // Only a drop that lands on the viewer itself loads a file;
        // dropping a photo anywhere else on the app page must not
        // hijack the viewer. (In the standalone viewer page there is
        // no #viewerBox and the canvas fills the window.)
        const box = document.getElementById("viewerBox");
        if (box && !box.contains(e.target)) return;
        if (e.dataTransfer.files[0]) selectFile(e.dataTransfer.files[0]);
    });

    let bytesRead = 0;
    let stopLoading = false;

    // ---- staged loader ----------------------------------------------
    // Posts partial buffers to the sort worker as rows accumulate, so
    // the model appears (and then densifies) long before the stage is
    // fully decoded, instead of waiting for the whole model + a full
    // sort. Progress is reported in decoded bytes, against the known
    // decoded size of our fixed assets.
    const progressEl = document.getElementById("progress");
    const messageEl = document.getElementById("message");
    const fmtKB = (n) => Math.round(n / 1024).toLocaleString("en-US");
    const showLoadProgress = (received, total, label) => {
        if (total > 0) {
            const pct = Math.min(100, Math.round((100 * received) / total));
            progressEl.style.display = "";
            progressEl.style.width = pct + "%";
            messageEl.innerText =
                label + " " + fmtKB(received) + " / " + fmtKB(total) + " KB（" + pct + "%）";
        } else {
            progressEl.style.display = "";
            messageEl.innerText = label + " " + fmtKB(received) + " KB";
        }
    };
    const clearLoadProgress = () => {
        progressEl.style.display = "none";
        if (!window.__splatFailed) messageEl.innerText = "";
        loaderOwnsProgress = false;
    };

    // ---- integrity-checked embedded data ------------------------------
    // The model data is already in the page, as string literals in
    // the statically-loaded program scripts; nothing is fetched and
    // nothing is dynamically loaded. It is still not trusted until
    // the decoded bytes match the manifest exactly.
    const CRC_TABLE = (() => {
        const t = new Uint32Array(256);
        for (let n = 0; n < 256; n++) {
            let c = n;
            for (let k = 0; k < 8; k++)
                c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
            t[n] = c >>> 0;
        }
        return t;
    })();
    const crc32 = (bytes) => {
        let c = 0xffffffff;
        for (let i = 0; i < bytes.length; i++)
            c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
        return (c ^ 0xffffffff) >>> 0;
    };
    const b64ToBytes = (b64) => {
        const pad = b64.endsWith("==") ? 2 : b64.endsWith("=") ? 1 : 0;
        const out = new Uint8Array((b64.length / 4) * 3 - pad);
        let o = 0;
        const CH = 1 << 18; // multiple of 4
        for (let off = 0; off < b64.length; off += CH) {
            const bin = atob(b64.slice(off, off + CH));
            for (let i = 0; i < bin.length; i++) out[o++] = bin.charCodeAt(i);
        }
        return out.subarray(0, o);
    };
    const checkB64 = (b64, expect) => {
        // Returns the decoded bytes when every check passes, else a
        // string describing what was actually received.
        if (typeof b64 !== "string" || !b64.length)
            return "未取得字串（全域值不存在或為空）";
        if (b64.length !== expect.b64Len)
            return "base64 長度 " + b64.length + " 字元（預期 " + expect.b64Len + "）";
        let bytes;
        try { bytes = b64ToBytes(b64); } catch (e) {
            return "base64 解碼失敗：" + (e.message || e);
        }
        if (bytes.length !== expect.bytes)
            return "解碼 " + bytes.length + " bytes（預期 " + expect.bytes + "）";
        const crc = crc32(bytes);
        if (crc !== expect.crc)
            return "CRC32 不符（收到 " + crc + "，預期 " + expect.crc + "）";
        return bytes;
    };
    // The full model's string lives in app.js, which the app page
    // loads right after this script; give it a moment to arrive
    // instead of failing instantly if this file's loader runs first.
    // (In the standalone viewer page app.js is absent: the wait
    // expires and the lite model simply stays on screen.)
    const waitForEmbedded = async (meta) => {
        const t0 = Date.now();
        for (;;) {
            const v = window[meta.global];
            if (typeof v === "string" && v.length) return v;
            if (Date.now() - t0 >= meta.waitMs) return null;
            await new Promise((r) => setTimeout(r, 100));
        }
    };
    // Read one embedded model and validate its decoded bytes against
    // the manifest (exact base64 length, decoded byte length, CRC32).
    const readEmbeddedModel = async (meta) => {
        const b64 = await waitForEmbedded(meta);
        if (b64 === null)
            throw new Error("內嵌模型資料未出現（全域 " + meta.global +
                " 為空，等待 " + meta.waitMs + " ms）；實際收到 0 bytes" +
                "（預期 base64 " + meta.b64Len + " 字元 / 解碼 " +
                meta.totalBytes + " bytes）");
        const checked = checkB64(b64, {
            b64Len: meta.b64Len, bytes: meta.totalBytes, crc: meta.crc,
        });
        if (!(checked instanceof Uint8Array))
            throw new Error("內嵌模型資料驗證失敗（全域 " + meta.global +
                "）：" + checked + "（預期 base64 " + meta.b64Len +
                " 字元 / 解碼 " + meta.totalBytes + " bytes）");
        return checked;
    };

    const finalizeStage = (buf) => {
        splatData = buf;
        bytesRead = buf.length;
        if (stopLoading) return;
        if (isPly(buf)) {
            // ply file magic header means it should be handled differently
            worker.postMessage({ ply: buf.buffer, save: false });
        } else {
            worker.postMessage({
                buffer: buf.buffer,
                vertexCount: Math.floor(buf.length / rowLength),
            });
            // A complete stage (lite, full, or a ?url= model):
            // (re)measure the orbit pivot from its gaussians.
            updateOrbitCenter(buf);
        }
    };

    // Post growing prefixes of a stage buffer to the sort worker so
    // the model appears (and then densifies) before the stage is
    // complete — the same progressive behaviour the old streaming
    // fetch had. Progress is reported in bytes against the stage's
    // known size.
    const postPrefix = (buf, rows) => {
        if (rows > 0 && !isPly(buf))
            worker.postMessage({ buffer: buf.buffer, vertexCount: rows });
    };
    const postProgressive = async (buf, totalBytes, label, postEveryRows) => {
        let postedRows = 0;
        const totalRows = Math.floor(buf.length / rowLength);
        for (let rows = postEveryRows; rows < totalRows; rows += postEveryRows) {
            postPrefix(buf, rows);
            postedRows = rows;
            showLoadProgress(rows * rowLength, totalBytes, label);
            await new Promise((r) => setTimeout(r, 0));
            if (stopLoading) break;
        }
        if (postedRows < totalRows) postPrefix(buf, totalRows);
    };

    // Decode one embedded model, posting growing prefixes to the
    // sort worker so the on-screen model densifies progressively —
    // the same presentation the old streaming loader had, with
    // decode progress in place of network progress. There is no
    // second channel to fall back to any more (the data is already
    // in the page); the staged fallbacks in loadModel — lite failure
    // goes straight to the full model, full failure keeps the lite
    // one — are what remains of the self-healing chain.
    const loadModelBytes = async (meta, label, postEveryRows) => {
        showLoadProgress(0, meta.totalBytes, label);
        let bytes;
        try {
            bytes = await readEmbeddedModel(meta);
        } catch (e) {
            throw new Error("模型資料載入失敗（預期 " + meta.totalBytes +
                " bytes / " + meta.count + " 點）。" + e.message);
        }
        await postProgressive(bytes, meta.totalBytes, label, postEveryRows);
        return bytes;
    };

    // ---- model loading (re-runnable) --------------------------------
    // The viewer used to be a separate page loaded into an iframe, and
    // switching models meant navigating that frame to a new URL. Some
    // hosts answer frame navigations into the assets folder with a
    // download instead of the page (the saved file gets a random
    // server-generated name), so the viewer now lives directly in the
    // app page and switching models is a plain function call — no
    // navigation anywhere in the model-switching path.
    let loadGeneration = 0;
    const loadModel = async (url) => {
        const gen = ++loadGeneration;
        stopLoading = true; // abort any in-flight decode loop
        await new Promise((r) => setTimeout(r, 0));
        if (gen !== loadGeneration) return;
        stopLoading = false;
        // Reset per-model state and tell the sort worker to forget the
        // previous model's texture, then re-show the loading UI.
        splatData = new Uint8Array(0);
        bytesRead = 0;
        vertexCount = 0;
        gotFirstSort = false;
        userMovedCamera = false;
        centroidKnown = false;
        loaderOwnsProgress = true;
        window.__splatFailed = false;
        worker.postMessage({ reset: true });
        document.getElementById("spinner").style.display = "";
        messageEl.innerText = "";
        progressEl.style.display = "";
        try {
            if (!url) {
                // Stage 1: decimated model -> fast first frame. If the
                // lite model cannot be obtained through either path,
                // go straight to the full model instead of showing an
                // empty viewer.
                let haveFull = false;
                try {
                    const liteBuf = await loadModelBytes(
                        MODEL_META.lite, "載入模型中…", 2048);
                    if (gen !== loadGeneration) return;
                    finalizeStage(liteBuf);
                } catch (liteErr) {
                    console.warn("lite 模型取得失敗，直接載入完整模型：", liteErr);
                    const fullBuf = await loadModelBytes(
                        MODEL_META.full, "載入模型中…", 16384);
                    if (gen !== loadGeneration) return;
                    finalizeStage(fullBuf);
                    haveFull = true;
                }
                // Stage 2: full model in the background; partial posts
                // make the on-screen model densify, the final post
                // swaps in all 76,276 gaussians. If this load fails,
                // the lite model simply stays.
                if (!haveFull) {
                    try {
                        const fullBuf = await loadModelBytes(
                            MODEL_META.full,
                            "快速版已顯示 · 完整模型載入中…",
                            16384);
                        if (gen !== loadGeneration) return;
                        finalizeStage(fullBuf);
                    } catch (e) {
                        /* lite model stays on screen */
                        console.warn("完整模型載入失敗，保留快速版：", e);
                    }
                }
            } else {
                // A blob: URL produced in-page by the app (the user's
                // own reconstruction). No host is involved, so a plain
                // fetch + arrayBuffer is safe and cannot be diverted
                // into a download.
                const resp = await fetch(url);
                if (!resp.ok)
                    throw new Error(resp.status + " Unable to load " + url);
                const bytes = new Uint8Array(await resp.arrayBuffer());
                if (gen !== loadGeneration) return;
                showLoadProgress(bytes.length, bytes.length, "載入模型中…");
                finalizeStage(bytes);
            }
        } catch (err) {
            if (gen === loadGeneration) {
                window.__splatFailed = true;
                document.getElementById("spinner").style.display = "none";
                messageEl.innerText = String(
                    err && err.message ? err.message : err,
                );
            }
            return;
        }
        if (gen !== loadGeneration) return;
        clearLoadProgress();
        // Watchdog: if the sort worker never answers (e.g. its Blob
        // URL was blocked from starting, which fails silently), swap
        // in the in-page shim worker and resend the model so the
        // viewer still renders instead of spinning forever.
        setTimeout(() => {
            if (gen !== loadGeneration) return;
            if (gotFirstSort || stopLoading || worker.isInlineShim) return;
            const dead = worker;
            worker = makeInlineShim();
            worker.onmessage = onWorkerMessage;
            if (dead.terminate) dead.terminate();
            if (isPly(splatData)) {
                worker.postMessage({ ply: splatData.buffer, save: false });
            } else {
                worker.postMessage({
                    buffer: splatData.buffer,
                    vertexCount: Math.floor(bytesRead / rowLength),
                });
            }
        }, 6000);
    };
    // API used by the app page (app.js) to switch models and to ask
    // the viewer to yield the CPU during heavy work.
    window.ClimbViewer = {
        showReference: () => loadModel(null),
        showUrl: (u) => loadModel(u),
        setPaused: (b) => {
            parentPaused = !!b;
        },
    };
    loadModel(requestedUrl);
}

window.__splatBooted = true;
main().catch((err) => {
    window.__splatFailed = true;
    document.getElementById("spinner").style.display = "none";
    document.getElementById("message").innerText = err.toString();
});
